const Footer = () => {
  const currentYear = new Date().getFullYear();

  return (
    <footer className="bg-[#b2541a] text-white py-10 mt-auto relative shadow-inner">

      {/* Decorative Border */}
      <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-[#7a3512] via-[#d97828] to-[#7a3512]" />

      <div className="container mx-auto px-4 text-center">

        {/* Main Text */}
        <h3 className="text-xl font-semibold tracking-wide">
          Bharat Connect
        </h3>

        <p className="text-orange-100 text-sm mt-1">
          Culture • Heritage • Innovation
        </p>

        {/* Divider */}
        <div className="w-24 h-[2px] bg-orange-100 mx-auto mt-4 mb-4 opacity-40" />

        {/* Copyright */}
        <p className="text-orange-200 text-sm">
          © {currentYear} Bharat Connect. All rights reserved.
        </p>

        {/* Tagline */}
        <p className="text-orange-100 text-xs mt-2">
          Celebrating India's timeless traditions and modern achievements.
        </p>
      </div>
    </footer>
  );
};

export default Footer;
